"""Exercise archive acquisition at the packaged-check command boundary."""

import hashlib
import io
import os
import shutil
import subprocess
import sys
import tarfile
import tempfile
import unittest
from pathlib import Path

SOURCE_ROOT = Path(sys.argv.pop(1)).resolve()


class PackagedArchiveTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="packaged-archive-test-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        subprocess.run(["git", "init", "--quiet", str(self.root)], check=True)
        scripts = self.root / ".github/scripts"
        scripts.mkdir(parents=True)
        for name in (
            "check-packaged-addon-control.sh",
            "download-verified.sh",
            "runner-image-target.sh",
        ):
            shutil.copyfile(SOURCE_ROOT / ".github/scripts" / name, scripts / name)
        self.script = scripts / "check-packaged-addon-control.sh"
        (self.root / "crates/runner/mitm-addon").mkdir(parents=True)
        self.binary = b"fixture standalone runtime\n"
        self.upstream = self.root / "upstream.tar.gz"
        self.make_archive(self.binary)
        self.cache = self.root / "cache/mitmproxy.tar.gz"
        self.cache.parent.mkdir()
        self.requests = self.root / "requests.jsonl"
        self.executed = self.root / "executed-binary"
        self.write_metadata()
        commands = self.root / "commands"
        commands.mkdir()
        self.command(commands / "uname", '#!/bin/sh\nprintf "%s\\n" "$TEST_ARCH"\n')
        self.command(
            commands / "curl",
            """#!/usr/bin/env python3
import json
import os
from pathlib import Path
import shutil
import sys

arguments = sys.argv[1:]
with Path(os.environ["TEST_REQUESTS"]).open("a") as requests:
    requests.write(json.dumps(arguments) + "\\n")
destination = Path(arguments[arguments.index("--output") + 1])
if os.environ["TEST_DOWNLOAD_MODE"] == "failure":
    destination.write_bytes(b"incomplete upstream response")
    sys.exit(28)
shutil.copyfile(os.environ["TEST_UPSTREAM"], destination)
""",
        )
        self.command(
            commands / "uv",
            """#!/usr/bin/env python3
import os
from pathlib import Path

binary = Path(os.environ["MITMDUMP_CONTROL_TEST_BINARY"])
Path(os.environ["TEST_EXECUTED"]).write_bytes(binary.read_bytes())
""",
        )
        self.environment = os.environ | {
            "PATH": f"{commands}:{os.environ['PATH']}",
            "TEST_ARCH": "x86_64",
            "TEST_REQUESTS": str(self.requests),
            "TEST_UPSTREAM": str(self.upstream),
            "TEST_DOWNLOAD_MODE": "success",
            "TEST_EXECUTED": str(self.executed),
            "MITMPROXY_CONTROL_TEST_ARCHIVE": str(self.cache),
            # Retry mechanics are covered by download-verified-test.sh.
            "OKOU_DOWNLOAD_VERIFIED_MAX_ATTEMPTS": "1",
            "OKOU_DOWNLOAD_VERIFIED_RETRY_DELAY_SECONDS": "0",
        }

    def command(self, path, source):
        path.write_text(source)
        path.chmod(0o755)

    def make_archive(self, binary):
        with tarfile.open(self.upstream, "w:gz") as archive:
            entry = tarfile.TarInfo("mitmdump")
            entry.size = len(binary)
            entry.mode = 0o755
            archive.addfile(entry, io.BytesIO(binary))

    def write_metadata(self, version="1.2.3", binary_sha=None):
        # Artifact metadata is a file input, using independently generated bytes.
        archive = self.upstream.read_bytes()
        archive_sha = hashlib.sha256(archive).hexdigest()
        binary_sha = binary_sha or hashlib.sha256(self.binary).hexdigest()
        lines = [f'pub const MITMPROXY_VERSION: &str = "{version}";']
        for arch in ("X86_64", "AARCH64"):
            lines.extend(
                [
                    f'pub const MITMPROXY_ARCHIVE_SHA256_{arch}: &str = "{archive_sha}";',
                    f"pub const MITMPROXY_ARCHIVE_SIZE_{arch}: u64 = {len(archive):_};",
                    f'pub const MITMDUMP_SHA256_{arch}: &str = "{binary_sha}";',
                    f"pub const MITMDUMP_SIZE_{arch}: u64 = {len(self.binary):_};",
                ]
            )
        (self.root / "crates/runner/src").mkdir(exist_ok=True)
        (self.root / "crates/runner/src/deps.rs").write_text("\n".join(lines) + "\n")

    def check(self, *arguments, **environment):
        return subprocess.run(
            ["bash", str(self.script), *arguments],
            cwd=self.root,
            env=self.environment | environment,
            text=True,
            capture_output=True,
            timeout=20,
            check=False,
        )

    def assert_success(self, result):
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_cold_archive_is_reused_without_an_upstream_request(self):
        self.assert_success(self.check())
        self.assertEqual(self.cache.read_bytes(), self.upstream.read_bytes())
        self.assertEqual(self.executed.read_bytes(), self.binary)
        requests = self.requests.read_text()
        self.executed.unlink()

        self.assert_success(self.check(TEST_DOWNLOAD_MODE="failure"))
        self.assertEqual(self.requests.read_text(), requests)
        self.assertEqual(self.executed.read_bytes(), self.binary)

    def test_cache_identity_tracks_version_architecture_and_archive_bytes(self):
        def key(**environment):
            result = self.check("--cache-key", **environment)
            self.assert_success(result)
            return result.stdout.strip()

        original = key()
        arm = key(TEST_ARCH="aarch64")
        self.write_metadata(version="1.2.4")
        new_version = key()
        self.make_archive(b"different upstream archive")
        self.write_metadata()
        new_archive = key()
        self.assertEqual(len({original, arm, new_version, new_archive}), 4)
        self.assertFalse(self.requests.exists())
        self.assertFalse(self.executed.exists())
        self.assertFalse(self.cache.exists())

    def test_corrupt_cached_archive_fails_before_tests_or_download(self):
        original = self.upstream.read_bytes()
        for corrupt in (original + b"extra", bytes([original[0] ^ 1]) + original[1:]):
            with self.subTest(size=len(corrupt)):
                self.cache.write_bytes(corrupt)
                result = self.check()
                self.assertNotEqual(result.returncode, 0)
                self.assertFalse(self.requests.exists())
                self.assertFalse(self.executed.exists())
                self.assertEqual(self.cache.read_bytes(), corrupt)

    def test_cached_archive_still_requires_the_pinned_binary_hash(self):
        shutil.copyfile(self.upstream, self.cache)
        self.write_metadata(binary_sha="0" * 64)
        result = self.check()
        self.assertNotEqual(result.returncode, 0)
        self.assertFalse(self.requests.exists())
        self.assertFalse(self.executed.exists())

    def test_failed_download_does_not_publish_partial_bytes_or_run_tests(self):
        result = self.check(TEST_DOWNLOAD_MODE="failure")
        self.assertNotEqual(result.returncode, 0)
        self.assertTrue(self.requests.exists())
        self.assertFalse(self.cache.exists())
        self.assertFalse(list(self.cache.parent.glob("*.partial.*")))
        self.assertFalse(self.executed.exists())


if __name__ == "__main__":
    unittest.main()
